grammar_engine_spec.javascript_reference_validator:
/**
 * Naadopaasana Dynamic Raga Grammar Validator (NRGV) v2.1
 * Comprehensive behavioral validation for notes and phrases:
 * - Varjya lockout
 * - Directional Arohana vs Avarohana rules
 * - Vakra phrase and forbidden leap detection
 * - Bhashanga Anya Swara phrase exceptions
 * - Vivadi intonation warnings
 * - Multi-octave symbol support (Ṡ, ṇ, etc.)
 */

function getBaseSwaraCode(code) {
  if (!code) return '';
  // Map Tara Shadja 'Ṡ' or Mandra Shadja to 'S'
  if (code.includes('Ṡ') || code.includes('S')) return 'S';
  return code.replace(/[·_̇\s,]/g, '');
}

/**
 * Validates a single note placement in real time.
 */
function validateSwaraPlacement(selectedSwara, ragaConfig, currentDirection = 'ASCENT', previousNotes = []) {
  const keys = ragaConfig.keys_palette || ragaConfig.palette_keys || [];
  const baseCode = getBaseSwaraCode(selectedSwara);
  const keyInfo = keys.find(k => k.code === selectedSwara || k.code === baseCode);

  if (!keyInfo) {
    return { status: 'INVALID', message: `Unknown Swara code '${selectedSwara}'`, color: '#9CA3AF' };
  }

  // 1. Check Anya Swara exceptions (Bhashanga ragas)
  if (keyInfo.status === 'ANYA_SWARA_EXCEPTION' || keyInfo.is_anya_swara) {
    const bhashangaRule = ragaConfig.bhashanga_rules?.find(b => b.anya_swara.startsWith(selectedSwara) || b.anya_swara.startsWith(baseCode));
    const allowedPhrase = bhashangaRule ? bhashangaRule.allowed_phrase.split(' ') : [];

    // Check if the preceding notes match the entry condition for the anya swara
    if (previousNotes.length > 0 && allowedPhrase.length > 0) {
      const targetIdx = allowedPhrase.findIndex(p => p === selectedSwara || p === baseCode);
      const precedingNeeded = allowedPhrase.slice(Math.max(0, targetIdx - previousNotes.length), targetIdx);
      const recentNotes = previousNotes.slice(-precedingNeeded.length).map(n => getBaseSwaraCode(n));
      const matches = precedingNeeded.every((n, i) => n === recentNotes[i]);

      if (matches) {
        return {
          status: 'WARNING_ANYA_SWARA',
          message: `Anya Swara ${selectedSwara} accepted within canonical phrase '${bhashangaRule.allowed_phrase}'.`,
          color: '#8B5CF6'
        };
      }
    }
    return {
      status: 'WARNING_ANYA_SWARA',
      message: `Anya Swara ${selectedSwara} used. Rule: ${bhashangaRule ? bhashangaRule.rule : 'Permitted only in specific prayogas'}`,
      color: '#8B5CF6'
    };
  }

  // 2. Check Varjya lockout
  if (keyInfo.status === 'LOCKED') {
    return {
      status: 'VIOLATION_VARJYA',
      message: `${selectedSwara} is varjya (strictly omitted) in ${ragaConfig.raga_name || ragaConfig.name}.`,
      color: '#EF4444'
    };
  }

  // 3. Check Directional Varjya (Arohana vs Avarohana)
  if (keyInfo.status === 'ACTIVE_ASCENT_ONLY' && currentDirection === 'DESCENT') {
    return {
      status: 'VIOLATION_VARJYA',
      message: `${selectedSwara} is permitted only in ascent (Ārohaṇa) of ${ragaConfig.raga_name || ragaConfig.name}.`,
      color: '#EF4444'
    };
  }
  if (keyInfo.status === 'ACTIVE_DESCENT_ONLY' && currentDirection === 'ASCENT') {
    return {
      status: 'VIOLATION_VARJYA',
      message: `${selectedSwara} is permitted only in descent (Avarohaṇa) of ${ragaConfig.raga_name || ragaConfig.name}.`,
      color: '#EF4444'
    };
  }

  // 4. Check Vakra phrase rules if raga is vakra
  if (ragaConfig.is_vakra && previousNotes.length > 0) {
    const ragaName = ragaConfig.raga_name || ragaConfig.name;
    const prev = getBaseSwaraCode(previousNotes[previousNotes.length - 1]);

    // Anandabhairavi checks
    if (ragaName === 'Ānandabhairavi' || ragaName === 'Anandabhairavi') {
      if (previousNotes.length >= 2) {
        const p2 = getBaseSwaraCode(previousNotes[previousNotes.length - 2]);
        if (p2 === 'S' && prev === 'R2' && baseCode === 'G2') {
          return {
            status: 'VIOLATION_VAKRA',
            message: `Ānandabhairavi requires vakra loop S G2 R2 G2 M1; linear S R G is forbidden.`,
            color: '#EC4899'
          };
        }
      }
    }

    // Ritigaula checks: ascent requires N2 N2 S to reach Tara S
    if (ragaName === 'Rītigauḷa' || ragaName === 'Reethigowla') {
      if ((selectedSwara === 'Ṡ' || baseCode === 'S') && currentDirection === 'ASCENT') {
        if (prev !== 'N2') {
          return {
            status: 'VIOLATION_VAKRA',
            message: `Rītigauḷa requires twin Nishada run (N2 N2 Ṡ) to reach Tāra Shaḍja; direct leap from ${prev} is forbidden.`,
            color: '#EC4899'
          };
        }
      }
    }
  }

  // 5. Vivadi Warning
  if (keyInfo.is_vivadi) {
    return {
      status: 'WARNING_VIVADI',
      message: `${selectedSwara} is a Vivādi swara. Requires precise microtonal intonation!`,
      color: '#F59E0B'
    };
  }

  return {
    status: 'ALLOWED',
    message: 'Swara perfectly valid in this raga.',
    color: '#10B981'
  };
}

/**
 * Validates a multi-note phrase in sequence against raga grammar.
 */
function validatePhrase(swaraArray, ragaConfig) {
  const results = [];
  const history = [];
  let currentDir = 'ASCENT';

  for (let i = 0; i < swaraArray.length; i++) {
    const swara = swaraArray[i];
    if (history.length > 0) {
      const prev = history[history.length - 1];
      const keys = ragaConfig.keys_palette || ragaConfig.palette_keys || [];
      const kCur = keys.find(k => k.code === swara || k.code === getBaseSwaraCode(swara));
      const kPrev = keys.find(k => k.code === prev || k.code === getBaseSwaraCode(prev));
      if (kCur && kPrev) {
        if (kCur.semitone_offset > kPrev.semitone_offset) currentDir = 'ASCENT';
        else if (kCur.semitone_offset < kPrev.semitone_offset) currentDir = 'DESCENT';
      }
    }

    const res = validateSwaraPlacement(swara, ragaConfig, currentDir, history);
    results.push({ index: i, swara, ...res });
    history.push(swara);
  }

  const hasErrors = results.some(r => r.status.startsWith('VIOLATION'));
  const hasWarnings = results.some(r => r.status.startsWith('WARNING'));

  return {
    is_valid: !hasErrors,
    has_warnings: hasWarnings,
    score: hasErrors ? 0 : (hasWarnings ? 85 : 100),
    step_results: results
  };
}
